look.customCSS:
/* ───── 信号故障 · 第一批 ───── */
[data-wk="chat"]{background:repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),url("data:image/svg+xml;base64,") 0 0/390px 420px,radial-gradient(ellipse at 50% 50%,#141418,#0B0B0D 75%) !important}
[data-wk="body"]{background:transparent !important}
[data-wk="chat"] *{font-family:"PingFang SC","Microsoft YaHei",sans-serif}

/* 顶栏：一条黑色信号条，底边红青两道错开的线 */
[data-wk="chathead"]{background:repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),#000 !important;border-bottom:none !important;box-shadow:0 1px 0 #19E6E6,0 3px 0 #FF2A55 !important}
[data-wk="headink"],[data-wk="headink"] *{color:#fff !important;text-shadow:-1.5px 0 0 #FF2A55,1.5px 0 0 #19E6E6 !important;letter-spacing:.1em !important;font-weight:700 !important}
[data-wk="headdim"],[data-wk="headname"] > div:last-child{color:#7A7A82 !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="headname"] > div:last-child::before{content:"● REC  " !important;color:#FF2A55 !important}
[data-wk="chatback"] svg{stroke:#fff !important;filter:drop-shadow(-1.5px 0 0 #FF2A55) drop-shadow(1.5px 0 0 #19E6E6) !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:26px !important;min-width:26px !important;height:26px !important;flex-shrink:0 !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;margin-left:4px !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}
[data-wk="chat"] [data-wk="chathead"] [data-wk="headme"]{display:inline-flex !important;margin-left:-6px !important}
[data-wk="chathead"] [data-wk="headme"] > *,[data-wk="chathead"] [data-wk="headme"] img,[data-wk="chathead"] [data-wk="avatar"]{width:32px !important;height:32px !important;min-width:32px !important;aspect-ratio:1 !important;border-radius:50% !important;box-shadow:-2px 0 0 1.5px #FF2A55,2px 0 0 1.5px #19E6E6 !important}
[data-wk="chathead"] [data-wk="headname"]{flex:1 1 auto !important;min-width:84px !important;margin-left:6px !important}

/* 头像：红青两层错开的圆环，各断几截 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *,[data-wk="msg"] [data-wk="avatar"],[data-wk="cardrow"] [data-wk="avatar"],[data-wk="rpsingle"] [data-wk="avatar"]{border-radius:50% !important}
[data-wk="body"] button[data-wk="avatar"],[data-wk="body"] span[data-wk="avatar"]:not([data-halo]){position:relative !important;overflow:visible !important;box-shadow:0 0 0 5px #1A1A20,-4px 0 0 8px #FF2A55,4px 0 0 8px #19E6E6 !important;margin:8px 8px !important}
[data-wk="body"] button[data-wk="avatar"]::after,[data-wk="body"] span[data-wk="avatar"]:not([data-halo])::after{content:"" !important;position:absolute !important;inset:-8px -12px !important;background:url("data:image/svg+xml;base64,") center/100% 100% no-repeat !important;pointer-events:none !important;z-index:2 !important}

/* 气泡：信号坏掉的屏幕——左红右青竖条、四角错位小方块、字带红青重影；我的是一块亮白屏 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border-radius:0 !important;line-height:1.6 !important;letter-spacing:.06em !important;font-weight:600 !important;padding:10px 18px !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),rgba(30,30,36,.85) !important;color:#fff !important;border:none !important;text-shadow:-1.5px 0 0 #FF2A55,1.5px 0 0 #19E6E6 !important;box-shadow:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,repeating-linear-gradient(180deg,rgba(0,0,0,.06) 0 1px,transparent 1px 3px),rgba(226,228,232,.92) !important;color:#111 !important;border:none !important;text-shadow:-1px 0 0 rgba(255,42,85,.6),1px 0 0 rgba(25,230,230,.6) !important;box-shadow:none !important}
/* 偶尔一抖：整块往旁边错一下 */
[data-wk="msg"]:nth-child(4n+2) [data-wk="bubble"][data-kind="text"]{animation:glJit 5s steps(1) infinite !important}
[data-wk="msg"]:nth-child(4n) [data-wk="bubble"][data-kind="text"]{animation:glJit 7s steps(1) infinite -3s !important}
@keyframes glJit{0%,92%{transform:none}93%{transform:translateX(3px)}95%{transform:translateX(-2px) skewX(-4deg)}97%,100%{transform:none}}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}

/* 时间：一行等宽小字，前面一个红点 */
[data-wk="time"] > span{background:none !important;border:none !important;box-shadow:none !important;color:#7A7A82 !important;font-family:ui-monospace,Menlo,monospace !important;font-size:11px !important;letter-spacing:.15em !important}
[data-wk="time"] > span::before{content:"▶ " !important;color:#FF2A55 !important}
/* 已读：一小格红青条；送达：一个空心圈 */
[data-wk="meta"]{color:#7A7A82 !important;font-size:10.5px !important;letter-spacing:.1em !important;display:inline-flex !important;align-items:center !important;gap:6px !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="meta"]::before{content:"" !important;width:16px !important;height:6px !important;background:linear-gradient(90deg,#FF2A55 0 50%,#19E6E6 50%) !important}
[data-wk="meta"][data-read="0"]::before{width:7px !important;height:7px !important;border-radius:50% !important;background:transparent !important;box-shadow:0 0 0 1.2px #7A7A82 !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{flex-direction:row-reverse !important}
[data-wk="msg"][data-last="0"] [data-wk="meta"]{display:none !important}
[data-run][data-last="1"] + [data-wk="cardmeta"]{display:block !important;font-size:10.5px !important;color:#7A7A82 !important;padding:2px 0 0 62px !important}
[data-run][data-last="1"] + [data-wk="cardmeta"][data-me="1"]{text-align:right !important;padding:2px 62px 0 0 !important}
[data-wk="bubble"][data-kind="typing"]{background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,rgba(30,30,36,.85) !important;border:none !important;border-radius:0 !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#fff !important;border-radius:0 !important;box-shadow:-1px 0 0 #FF2A55,1px 0 0 #19E6E6 !important}

/* 动描：一段字幕——黑底半透明一条，等宽灰字，前后各一个方括号 */
[data-wk="narr"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="narrink"],[data-wk="myactink"]{display:inline-block !important;background:rgba(0,0,0,.55) !important;border:none !important;border-radius:0 !important;box-shadow:none !important;backdrop-filter:none !important;-webkit-backdrop-filter:none !important;color:#B9B9C0 !important;opacity:1 !important;font-style:normal !important;font-family:ui-monospace,Menlo,monospace !important;font-size:12px !important;line-height:1.75 !important;padding:4px 12px !important}
[data-wk="narrink"]::before,[data-wk="myactink"]::before{content:"[ " !important;color:#19E6E6 !important}
[data-wk="narrink"]::after,[data-wk="myactink"]::after{content:" ]" !important;color:#FF2A55 !important}
[data-wk="sysnote"]{background:transparent !important;border:none !important;box-shadow:none !important}
[data-wk="sysnotelabel"]{display:none !important}
[data-wk="sysnotetext"]{background:transparent !important;border:none !important;color:#7A7A82 !important;font-family:ui-monospace,Menlo,monospace !important;font-size:11px !important;font-style:normal !important}
[data-wk="sysnotetext"]::before{content:"ERR · " !important;color:#FF2A55 !important}
[data-wk="narrbar"]{background:#000 !important;border-top:1px solid #222 !important}
[data-wk="narrkind"]{border:1px solid #333 !important;border-radius:0 !important;background:transparent !important;color:#7A7A82 !important}
[data-wk="narrkind"][data-on="1"]{border-color:#19E6E6 !important;color:#fff !important;box-shadow:-2px 0 0 #FF2A55 !important}

/* 底栏：黑色信号条；左红青十字加号、黑框输入框、右红青重影的播放键发送、像素对话框回复 */
[data-wk="composer"]{background:repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),#000 !important;border-top:none !important;box-shadow:0 -1px 0 #FF2A55,0 -3px 0 #19E6E6 !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,#141418 !important;border:none !important;border-radius:0 !important;color:#fff !important}
[data-wk="chatinput"]::placeholder{color:#555 !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="chatplus"]{width:28px !important;min-width:28px !important;height:28px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] svg{display:none !important}
[data-wk="send"]{width:36px !important;min-width:36px !important;height:36px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;opacity:1 !important}
[data-wk="chatreply"]{width:40px !important;min-width:40px !important;height:34px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}

/* 打电话那一屏：黑底扫描线；三个键是红青错开的方块 */
[data-wk="call"][data-video="0"]{background:repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),url("data:image/svg+xml;base64,") 0 0/390px 420px,#000 !important}
[data-wk="calltitle"]{color:#fff !important;text-shadow:-1.5px 0 0 #FF2A55,1.5px 0 0 #19E6E6 !important;letter-spacing:.15em !important}
[data-wk="callavatar"]{border-radius:50% !important;box-shadow:-5px 0 0 3px #FF2A55,5px 0 0 3px #19E6E6,0 0 30px rgba(25,230,230,.3) !important}
[data-wk="callbtns"] button > span:first-child{background:#111 !important;border-radius:0 !important;box-shadow:-3px 0 0 #FF2A55,3px 0 0 #19E6E6 !important}
[data-wk="callbtns"] button > span:first-child svg{stroke:#fff !important}
[data-wk="callbtns"] button:nth-child(2) > span:first-child{background:#FF2A55 !important;box-shadow:3px 3px 0 #19E6E6 !important}
[data-wk="call"][data-video="0"] [data-wk="callbtns"] button > span:last-child{color:#7A7A82 !important}
[data-wk="callbubble"]{background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,rgba(30,30,36,.85) !important;color:#fff !important;border:none !important;border-radius:0 !important}
[data-wk="callmsg"][data-me="1"] [data-wk="callbubble"]{background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,rgba(226,228,232,.92) !important;color:#111 !important}
[data-wk="callbubble"]::before,[data-wk="callbubble"]::after{content:none !important}
[data-wk="note"][data-part="callsum"]{display:block !important;margin:6px auto 0 !important;background:rgba(0,0,0,.55) !important;border:none !important;border-left:3px solid #19E6E6 !important;border-radius:0 !important;padding:8px 14px !important;color:#B9B9C0 !important;font-family:ui-monospace,Menlo,monospace !important;font-size:11.5px !important;text-align:left !important}
[data-wk="noteink"]{color:#7A7A82 !important}
[data-wk="callact"]{color:#19E6E6 !important}

/* ───── 信号故障 · 第二批：卡片（形状不动；每张都是一块取景器框住的暗屏，左上角写着它是什么） ───── */
[data-wk="transfercard"],[data-wk="photocard"],[data-wk="geocard"] > [data-wk="card"],[data-wk="namecard"],[data-part="offlog"],[data-wk="callpill"] > [data-wk="block"],[data-wk="wxcard"]{position:relative !important;overflow:visible !important;background:linear-gradient(#FF2A55,#FF2A55) left top/2px 12px no-repeat,linear-gradient(#FF2A55,#FF2A55) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),rgba(30,30,36,.88) !important;border:none !important;border-radius:0 !important;box-shadow:none !important;color:#fff !important;padding-top:22px !important}
[data-wk="transfercard"] *,[data-wk="namecard"] *,[data-part="offlog"] *,[data-wk="geocard"] *,[data-wk="callpill"] *,[data-wk="photocard"] *,[data-wk="wxcard"] *{color:#E6E6EA !important;border-color:#2C2C33 !important}
[data-wk="transfercard"]::before{content:"TRANSFER" !important;position:absolute !important;left:10px !important;top:6px !important;font:700 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;color:#19E6E6 !important;background:none !important;border:none !important;width:auto !important;height:auto !important;transform:none !important;z-index:3 !important}
[data-wk="photocard"]::before{content:"IMG_0001" !important;position:absolute !important;left:10px !important;top:6px !important;font:700 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;color:#19E6E6 !important;background:none !important;border:none !important;width:auto !important;height:auto !important;transform:none !important;z-index:3 !important}
[data-wk="wxcard"]::before{content:"WEATHER.LOG" !important;position:absolute !important;left:10px !important;top:6px !important;font:700 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;color:#19E6E6 !important;background:none !important;border:none !important;width:auto !important;height:auto !important;transform:none !important;z-index:3 !important}
[data-wk="namecard"]::before{content:"CONTACT" !important;position:absolute !important;left:10px !important;top:6px !important;font:700 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;color:#19E6E6 !important;background:none !important;border:none !important;width:auto !important;height:auto !important;transform:none !important;z-index:3 !important}
[data-part="offlog"]::before{content:"REPLAY" !important;position:absolute !important;left:10px !important;top:6px !important;font:700 10px/1 ui-monospace,Menlo,monospace !important;letter-spacing:.15em !important;color:#FF2A55 !important;background:none !important;border:none !important;width:auto !important;height:auto !important;transform:none !important;z-index:3 !important}
[data-wk="transferamount"],[data-wk="transfercur"]{color:#fff !important;text-shadow:-1.5px 0 0 #FF2A55,1.5px 0 0 #19E6E6 !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="transferrule"]{border:none !important;height:1px !important;background:linear-gradient(90deg,#FF2A55,#19E6E6) !important}
[data-wk="transfernotch"]{display:none !important}
[data-wk="transferfoot"]{background:transparent !important;border-top:1px solid #2C2C33 !important}
[data-wk="transferbtn"]{border-radius:0 !important;background:transparent !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="transferbtn"][data-part="take"]{border:1px solid #19E6E6 !important;color:#19E6E6 !important;box-shadow:-2px 0 0 #FF2A55 !important}
[data-wk="transferbtn"][data-part="back"]{border:1px solid #444 !important;color:#7A7A82 !important}
[data-wk="transferseal"]{background:transparent !important;border:2px solid #19E6E6 !important;border-radius:0 !important;color:#19E6E6 !important;box-shadow:-3px 0 0 #FF2A55 !important;font-family:ui-monospace,Menlo,monospace !important;transform:rotate(-6deg) !important}
[data-wk="transferseal"] *{color:#19E6E6 !important}
[data-wk="transfercard"][data-status="returned"]{opacity:.45 !important}
/* 红包：一块红色的报错屏，左边一个 ⚠；领完变灰 */
[data-wk="rpcard"]{position:relative !important;overflow:visible !important;background:linear-gradient(#fff,#fff) left top/2px 12px no-repeat,linear-gradient(#fff,#fff) left top/12px 2px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/2px 12px no-repeat,linear-gradient(#19E6E6,#19E6E6) right bottom/12px 2px no-repeat,repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),linear-gradient(90deg,#8E1430,#FF2A55) !important;border:none !important;border-radius:0 !important;box-shadow:3px 3px 0 #19E6E6 !important;padding-left:52px !important}
[data-wk="rpcard"]::before{content:"⚠" !important;position:absolute !important;left:16px !important;top:calc(50% - 14px) !important;font-size:24px !important;line-height:28px !important;color:#fff !important;text-shadow:-1.5px 0 0 #FF2A55,1.5px 0 0 #19E6E6 !important}
[data-wk="rpcard"] *{color:#fff !important}
[data-wk="rpflap"],[data-wk="rpseal"],[data-wk="rpcorner"]{display:none !important}
[data-wk="rpcard"][data-status="done"]{filter:grayscale(1) !important;opacity:.6 !important}
[data-wk="rpenvelope"]{background:repeating-linear-gradient(180deg,rgba(255,255,255,.035) 0 1px,transparent 1px 3px),linear-gradient(180deg,#8E1430,#3A0614) !important;border:none !important;border-radius:0 !important;box-shadow:-6px 0 0 #FF2A55,6px 0 0 #19E6E6 !important}
[data-wk="rpenvelope"] [data-wk="rparc"]{background:transparent !important;border:none !important}
[data-wk="rpenvelope"] *{color:#fff !important}
[data-wk="rpopenbtn"]{background:#000 !important;border:2px solid #fff !important;border-radius:0 !important;box-shadow:-4px 0 0 #FF2A55,4px 0 0 #19E6E6 !important}
[data-wk="rpopenbtn"] *{color:#fff !important}
[data-wk="rpamount"]{color:#fff !important;text-shadow:-1.5px 0 0 #FF2A55,1.5px 0 0 #19E6E6 !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="rpavatar"],[data-wk="rpavatar"] *{border-radius:50% !important}
[data-wk="rpavatar"]{box-shadow:0 0 0 4px #1A1A20,-4px 0 0 7px #FF2A55,4px 0 0 7px #19E6E6 !important}
/* 照片：一块雪花屏 */
[data-wk="photocard"]{padding:22px 8px 10px !important}
[data-wk="photoface"]{border-radius:0 !important;background:repeating-linear-gradient(180deg,rgba(255,255,255,.08) 0 1px,transparent 1px 2px),repeating-linear-gradient(90deg,rgba(255,255,255,.05) 0 1px,transparent 1px 3px),#222 !important;border:none !important;box-shadow:none !important}
[data-wk="photoface"] *,[data-wk="photohint"]{color:#C8C8D0 !important;font-family:ui-monospace,Menlo,monospace !important}
[data-wk="photoface"] svg{stroke:#19E6E6 !important}
[data-wk="photocard"] > img{border-radius:0 !important;filter:contrast(1.1) saturate(.9) !important;box-shadow:-3px 0 0 #FF2A55,3px 0 0 #19E6E6 !important}
